import tokens, { Tokens } from "@airbus/design-tokens";

export type ThemeTokens = Tokens;

/**
 * take the tokens and add color modes utilities
 * @param brandName
 * @returns tokens with augmented color modes
 */
export default function createTheme(brandName = "airbus"): ThemeTokens {
  if (!tokens[brandName] && process.env.NODE_ENV !== "production") {
    console.error(`[AIRBUS] the brand \`${brandName}\` is not supported.`);
    return {} as ThemeTokens;
  }

  return tokens[brandName];
}
